contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(address payable target, uint256 value, bytes memory data) public payable {
        require(address(this).balance >= value, "insufficient test balance");

        // Distinguish the two possible conditions: target must not be c, and c's balance relative to value.
        // The target is an EOA-like address: an empty call succeeds but no code runs.
        // First, record whether c currently has enough Ether to attempt a transfer of `value`.
        bool hasEnough = address(c).balance >= value;

        // Setup: check the target accepts a plain zero-value call (no calldata).
        (bool targetOk, ) = target.call{value: 0}("");

        // Deciding call through c's public entry `sendMoney`, at top level.
        bool reverted;
        try c.sendMoney(target, value, data) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 cBalanceAfter = address(c).balance;

        // General rule: sendMoney succeeds exactly when c has enough Ether and the target accepts
        // the zero-value empty call; on revert, c's balance is unchanged (the deciding call has no side effects).
        if (targetOk && hasEnough) {
            assert(!reverted);
        } else {
            assert(reverted);
        }
    }
}

