contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint depositAmount) public payable {
        address owner = c.owner();
        bool isOwner = (owner == address(this));

        // Build the pre-call state: depositsCount > 0 and c holds some Ether.
        require(address(this).balance >= depositAmount);
        c.depositsCount();
        c.fallback{value: depositAmount}();

        uint beforeBalance = address(c).balance;
        uint beforeDepositsCount = c.depositsCount();
        uint beforeThisBalance = address(this).balance;

        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterBalance = address(c).balance;
        uint afterDepositsCount = c.depositsCount();
        uint afterThisBalance = address(this).balance;

        assert(
            (isOwner
                ? (!reverted
                    && afterBalance == 0
                    && afterThisBalance == beforeThisBalance + beforeBalance
                    && afterDepositsCount == beforeDepositsCount)
                : (reverted
                    && afterBalance == beforeBalance
                    && afterThisBalance == beforeThisBalance
                    && afterDepositsCount == beforeDepositsCount))
        );
    }

    receive() external payable {}
}

